import{_ as a,o,c as r,a2 as i}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E5%90%8E%E7%AB%AF%E9%85%8D%E7%BD%AE-boot.BFGXmEhj.png",t="/newx-doc/assets/%E7%94%9F%E6%88%90%E5%B0%8F%E7%A8%8B%E5%BA%8F%E7%A0%81.dic-gHXH.png",_=JSON.parse('{"title":"微信小程序码","description":"","frontmatter":{},"headers":[],"relativePath":"member/weixin-lite-qrcode.md","filePath":"member/weixin-lite-qrcode.md","lastUpdated":null}'),d={name:"member/weixin-lite-qrcode.md"};function c(n,e,p,s,m,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="微信小程序码" tabindex="-1">微信小程序码 <a class="header-anchor" href="#微信小程序码" aria-label="Permalink to &quot;微信小程序码&quot;">​</a></h1><p>前置阅读文章：</p><ul><li><a href="./../user-center">《用户体系》</a></li><li><a href="./../social-user">《三方登录》</a></li></ul><p>本文是 <a href="./../social-user">《三方登录》</a> 的延伸，讲解 <a href="https://github.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer"><code>yudao-mall-uniapp</code></a> 商城小程序如何实现微信 <strong>小程序</strong> 码的功能。对应的官方文档如下：</p><ul><li><a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/qrcode-link/qr-code/getQRCode.html" target="_blank" rel="noreferrer">《【服务端】小程序码》</a></li></ul><h2 id="_1-小程序准备" tabindex="-1">1. 小程序准备 <a class="header-anchor" href="#_1-小程序准备" aria-label="Permalink to &quot;1. 小程序准备&quot;">​</a></h2><p>在后端 <a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/qrcode-link/qr-code/getUnlimitedQRCode.html" target="_blank" rel="noreferrer">生成小程序码</a> 时，需要传递 <code>env_version</code> 参数，要打开的小程序版本：</p><ul><li><code>release</code> 为正式版为</li><li><code>trial</code> 为体验版</li><li><code>develop</code> 为开发版</li></ul><p>因此，在 <code>application-${profile}.yaml</code> 配置文件中，有对应的 <code>yudao.wxa-code.env-version</code> 配置项，如下图所示：</p><p><img src="'+l+'" alt="后端配置"></p><p>一般情况下，如果是开发测试，不用修改，直接使用默认的 <code>develop</code> 即可。</p><h2 id="_2-功能演示-代码实现" tabindex="-1">2. 功能演示 &amp; 代码实现 <a class="header-anchor" href="#_2-功能演示-代码实现" aria-label="Permalink to &quot;2. 功能演示 &amp; 代码实现&quot;">​</a></h2><p>本小节，我们以【商城】分销的分享二维码为例，演示如何实现小程序码的功能。在开始之前，你需要做如下事情：</p><ul><li>参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档，把 <code>yudao-uniapp-mall</code> 商城项目跑起来，并使用 HBuilderX + 微信开发者工具进行调试</li><li>参考 <a href="./../mall/build">《商城功能开启》</a> 文档，开启商城功能</li></ul><p>点击 uni-app 的【分销中心】，然后点击【邀请海报】按钮，之后点击【生成海报】按钮，即可生成小程序码。如下图所示：</p><p><img src="'+t+'" alt="生成小程序码"></p><p>这里，它调用的是 AppSocialUserController 的 <code>#getWxaQrcode(...)</code> 方法，提供的 HTTP 接口。它的内部，调用 SocialClientApi 的 <code>#getWxaQrcode(...)</code> 方法，从而调用微信的 <a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/qrcode-link/qr-code/getUnlimitedQRCode.html" target="_blank" rel="noreferrer">生成小程序码</a> 接口，生成小程序码。</p>',17)])])}const f=a(d,[["render",c]]);export{_ as __pageData,f as default};
